#include <memory>
#include <stdexcept>
#include "../athena.hpp"
#include "../athena_arrays.hpp"
#include "../bvals/bvals.hpp"
#include "../coordinates/coordinates.hpp"
#include "../eos/eos.hpp"
#include "../hydro/hydro.hpp"
#include "../mesh/mesh.hpp"
#include "../parameter_input.hpp"
#include "x3i_boundary.hpp"

#if MAGNETIC_FIELDS_ENABLED
#error "x3i_wind is an independent hydrodynamic control; do not enable magnetic fields"
#endif

namespace {
using State=std::array<double,5>;
using x3i::V;
using x3i::dot;
using x3i::mul;
using x3i::add;
std::unique_ptr<x3i::Config> cfg;
std::unique_ptr<x3i::Boundary> boundary;
double gamma_gas, rmin, previous_day, minimum_density=1e99,minimum_pressure=1e99;
double maximum_inner_mass_flux_error=0, minimum_inflow_mach=1e99;
int nr, nt, np;
std::vector<double> radii,thetas,phis;
std::vector<State> previous;
struct Probe {double day,r,lon,lat;int id;};
std::vector<Probe> probes;
size_t next_probe=0;
std::ofstream probe_out;
std::filesystem::path output;

V er(double t,double p){return {std::sin(t)*std::cos(p),std::sin(t)*std::sin(p),std::cos(t)};}
V et(double t,double p){return {std::cos(t)*std::cos(p),std::cos(t)*std::sin(p),-std::sin(t)};}
V ep(double p){return {-std::sin(p),std::cos(p),0};}
size_t index(int i,int j,int k){return ((size_t)i*nt+j)*np+k;}

// Return density, radial/polar/azimuthal velocity, pressure in solver units.
State analytic(double day,double radius,double theta,double phi,bool retard) {
  double lag=retard?(radius-rmin)/((boundary->speed+boundary->speed_offset)*1000/x3i::VUNIT):0;
  auto b=boundary->sample(day-lag,phi,x3i::X3IPI/2-theta);
  double density=b[1]/(radius*radius), v=b[0]*1000/x3i::VUNIT;
  double temperature=b[3]*std::pow(radius/rmin,-2*(gamma_gas-1));
  double pressure=cfg->d("thermal_pressure_factor",2)*density*1e6*x3i::KB*temperature/x3i::PUNIT;
  double vp=cfg->d("boundary_vphi_kms",0)*1000/x3i::VUNIT*rmin/radius;
  return {density,v,0,vp,pressure};
}

void inner(MeshBlock*,Coordinates*co,AthenaArray<Real>&w,FaceField&,Real day,Real,
           int il,int,int jl,int ju,int kl,int ku,int ngh) {
  for(int k=kl;k<=ku;++k)for(int j=jl;j<=ju;++j){
    State z=analytic(day,rmin,co->x2v(j),co->x3v(k),false);
    // Constant ghost states make the left PLM interface state exactly equal to
    // the imposed face state. For supersonic HLLC inflow its physical flux is
    // therefore the same prescribed flux as the in-house hydro calculation.
    for(int i=il-ngh;i<il;++i){w(IDN,k,j,i)=z[0];w(IVX,k,j,i)=z[1];
      w(IVY,k,j,i)=z[2];w(IVZ,k,j,i)=z[3];w(IPR,k,j,i)=z[4];}
  }
}

std::vector<State> capture(MeshBlock* block) {
  std::vector<State> states((size_t)nr*nt*np);
  auto&u=block->phydro->u;
  for(int i=0;i<nr;++i)for(int j=0;j<nt;++j)for(int k=0;k<np;++k){
    int ii=i+block->is,jj=j+block->js,kk=k+block->ks;
    V e=er(thetas[j],phis[k]),t=et(thetas[j],phis[k]),p=ep(phis[k]);
    V momentum=add(add(mul(e,u(IM1,kk,jj,ii)),mul(t,u(IM2,kk,jj,ii))),mul(p,u(IM3,kk,jj,ii)));
    State z={u(IDN,kk,jj,ii),momentum[0],momentum[1],momentum[2],u(IEN,kk,jj,ii)};
    double pressure=(gamma_gas-1)*(z[4]-.5*(z[1]*z[1]+z[2]*z[2]+z[3]*z[3])/z[0]);
    if(!(z[0]>1e-15&&pressure>1e-15&&std::isfinite(pressure)))
      throw std::runtime_error("Independent hydro state became nonphysical or approached its configured floor");
    minimum_density=std::min(minimum_density,z[0]);minimum_pressure=std::min(minimum_pressure,pressure);
    states[index(i,j,k)]=z;
  }
