}

State sample(const std::vector<State>&s,const Probe&q) {
  auto bracket=[](const std::vector<double>&v,double x){
    if(x<v.front()-1e-10||x>v.back()+1e-10)throw std::runtime_error("Probe outside cell-center interpolation domain");
    int i=std::clamp(int(std::upper_bound(v.begin(),v.end(),x)-v.begin())-1,0,int(v.size())-2);
    return std::pair<int,double>{i,(x-v[i])/(v[i+1]-v[i])};};
  auto [i,fi]=bracket(radii,q.r);auto[j,fj]=bracket(thetas,x3i::X3IPI/2-q.lat);
  double kp=x3i::wrap(q.lon)/(2*x3i::X3IPI/np)-.5;int k=std::floor(kp);double fk=kp-k;
  State z={};
  for(int di=0;di<2;++di)for(int dj=0;dj<2;++dj)for(int dk=0;dk<2;++dk){
    double w=(di?fi:1-fi)*(dj?fj:1-fj)*(dk?fk:1-fk);
    const State&a=s[index(i+di,j+dj,((k+dk)%np+np)%np)];
    for(int v=0;v<5;++v)z[v]+=w*a[v];
  }
  return z;
}

void write_probe(const Probe&q,const std::vector<State>&current,double current_day) {
  State left=sample(previous,q),right=sample(current,q),z;
  double f=current_day==previous_day?1:std::clamp((q.day-previous_day)/(current_day-previous_day),0.,1.);
  for(int v=0;v<5;++v)z[v]=(1-f)*left[v]+f*right[v];
