  f.write(h.data(),h.size());f.write(reinterpret_cast<const char*>(v.data()),v.size()*sizeof(float));
  if(!f)throw std::runtime_error("Cannot save independent hydro snapshot");
}
}

void Mesh::InitUserMeshData(ParameterInput*pin) {
  cfg.reset(new x3i::Config(pin->GetString("problem","config_file")));
  boundary.reset(new x3i::Boundary(*cfg));gamma_gas=cfg->d("gamma",1.5);rmin=cfg->d("rmin_au",.1);
  if(std::abs(gamma_gas-pin->GetReal("hydro","gamma"))>1e-12)throw std::runtime_error("Gamma mismatch");
  output=pin->GetString("problem","output_dir");std::filesystem::create_directories(output);
  EnrollUserBoundaryFunction(BoundaryFace::inner_x1,inner);
  x3i::Csv csv(cfg->s("probes_csv"));int it=csv.col("day"),ir=csv.col("r_au"),ip=csv.col("lon_rad"),il=csv.col("lat_rad"),id=csv.col("probe_id",false);
  for(auto&z:csv.rows)probes.push_back({z[it],z[ir],z[ip],z[il],id<0?0:int(z[id])});
  std::sort(probes.begin(),probes.end(),[](const Probe&a,const Probe&b){return a.day<b.day;});
