    npy(output/a.first,std::vector<float>(a.second.begin(),a.second.end()),{int(a.second.size())});
  std::ofstream manifest(output/"snapshots.csv");manifest<<"day,file\n"<<std::setprecision(12)<<time<<",snapshot_00000.npy\n";
  std::ofstream stats(output/"statistics.json");stats<<std::setprecision(12)
    <<"{\"steps\":"<<ncycle<<",\"minimum_density_cm3\":"<<minimum_density<<",\"minimum_pressure_code\":"<<minimum_pressure
    <<",\"floor_activations\":0,\"strict_floor_abort\":true,\"maximum_relative_inner_mass_flux_error\":"<<maximum_inner_mass_flux_error
